<?php
if(PHP_SAPI!=='cli'||$argc<2)exit(2);$command=json_decode((string)file_get_contents($argv[1]),true);if(!is_array($command))exit(3);require_once dirname(__DIR__,2).'/app/application.php';$_SESSION=['user_id'=>(int)$command['user_id'],'role'=>$command['role'],'agency_ids'=>[(int)$command['agency_id']], '_authenticated_at'=>time()];$barrier=$command['barrier'];$label=$command['label'];file_put_contents($barrier.'/'.$label.'.ready','ready');$deadline=microtime(true)+15;while(!is_file($barrier.'/go')){if(microtime(true)>$deadline){file_put_contents($command['result'],json_encode(['ok'=>false,'error'=>'barrier timeout']));exit(4);}usleep(10000);}try{$args=$command['args'];$result=match($command['operation']){'payment'=>recordSettledPayment($args),'adjustment'=>appendPaymentAdjustment($args),'close'=>closeCashRegister($args),'invoice_draft'=>createInvoiceDraftFromReservation($args),'invoice_issue'=>issueInvoice($args),'invoice_create_issue'=>createAndIssueInvoiceFromReservation($args),'credit_note'=>issueCreditNote($args),'expense_decide'=>decideExpense($args),'deposit_event'=>appendDepositEvent($args),default=>throw new InvalidArgumentException('unknown worker operation')};file_put_contents($command['result'],json_encode(['ok'=>true,'result'=>$result]));}catch(Throwable$e){file_put_contents($command['result'],json_encode(['ok'=>false,'class'=>get_class($e)]));}
